<script setup>
import { ref } from 'vue'
import { ChevronRight, LockKeyhole, Sparkles, Unlock } from 'lucide-vue-next'
import { useI18n } from '../i18n'
const props = defineProps({ components: Array, locked: Array, models: Array, loading: Boolean, unlockAction: Function })
const unlocking = ref('')
const { t } = useI18n()
function methodsOf(component) { return component.unlock?.methods || [] }
function methodLabel(method) { if (method.type === 'energy_coins') return t('creatures.energyCost', { amount: method.amount }); if (method.type === 'gold_coins') return t('creatures.goldCost', { amount: method.amount }); return t('creatures.achievement', { id: method.achievement_id }) }
async function unlock(component) { unlocking.value = component.id; try { await props.unlockAction(component.id) } finally { unlocking.value = '' } }
</script>
<template><section class="content"><div class="page-intro"><div><span class="eyebrow cyan-text">{{ t('labels.creaturesEyebrow') }}</span><h2>{{ t('nav.creatures') }}</h2><p>{{ t('creatures.subtitle') }}</p></div></div><div v-if="loading" class="empty-state">{{ t('creatures.loading') }}</div><div v-else class="lab-grid"><div class="table-card lab-panel"><div class="card-header"><div><span class="eyebrow">{{ t('labels.unlocked') }}</span><h3>{{ t('creatures.unlocked') }}</h3></div><span class="count-badge">{{ components.length }}</span></div><div v-if="!components.length" class="panel-empty">{{ t('creatures.noneUnlocked') }}</div><div v-for="component in components" :key="component.id" class="component-row"><span class="component-glyph"><Sparkles :size="16" /></span><div><b>{{ component.name }}</b><small>{{ component.id }} · {{ component.category }}</small></div><ChevronRight :size="15" /></div></div><div class="table-card lab-panel"><div class="card-header"><div><span class="eyebrow">{{ t('labels.catalog') }}</span><h3>{{ t('creatures.locked') }}</h3></div><span class="count-badge">{{ locked.length }}</span></div><div v-if="!locked.length" class="panel-empty">{{ t('creatures.noneLocked') }}</div><div v-for="component in locked" :key="component.id" class="component-row"><span class="component-glyph violet"><LockKeyhole :size="16" /></span><div><b>{{ component.name }}</b><small>{{ component.id }} · {{ methodsOf(component).map(methodLabel).join(' / ') || t('creatures.noMethod') }}</small></div><button class="unlock-btn" :disabled="unlocking === component.id || !methodsOf(component).length" @click="unlock(component)"><Unlock :size="14" />{{ unlocking === component.id ? t('common.processing') : t('creatures.unlock') }}</button></div></div><div class="table-card lab-panel model-composition-panel"><div class="card-header"><div><span class="eyebrow">{{ t('labels.compositions') }}</span><h3>{{ t('creatures.compositions') }}</h3></div><span class="count-badge">{{ models.length }}</span></div><div v-if="!models.length" class="panel-empty">{{ t('creatures.noneModels') }}</div><div v-for="model in models" :key="model.id" class="component-row"><span class="component-glyph violet"><LockKeyhole :size="16" /></span><div><b>{{ model.name }}</b><small>{{ model.id }} · {{ t('common.count', { count: Object.keys(model.composition?.components || {}).length }) }}</small></div></div></div></div></section></template>
